mapper.update:
UPDATE zw_teacher
USER_ID = #{userId}, SEX = #{sex}, TEACHER_CODE = #{teacherCode}, TEACH_SUBJECT = #{teachSubject}, TEACHER_STATUS = #{teacherStatus}, TEACHER_TYPE = #{teacherType}, PHONE = #{phone}, GRA = #{gra}, CLA = #{cla},
WHERE TEACHER_ID = #{teacherId}

mapper.select:
SELECT t.*, u.USER_NAME, u.NAME, sex.CODE_DESC as SEX_DESC, ts.CODE_DESC as TEACHER_STATUS_DESC, tt.CODE_DESC as TEACHER_TYPE_DESC, sub.CODE_DESC as TEACH_SUBJECT_DESC FROM zw_teacher t LEFT JOIN g_user u ON t.USER_ID = u.USER_ID LEFT JOIN g_code sex ON t.SEX = sex.CODE_ID LEFT JOIN g_code ts ON t.TEACHER_STATUS = ts.CODE_ID LEFT JOIN g_code tt ON t.TEACHER_TYPE = tt.CODE_ID LEFT JOIN g_code sub ON t.TEACH_SUBJECT = sub.CODE_ID
AND t.TEACH_SUBJECT = #{teachSubject}
AND t.GRA = #{gra}
AND t.CLA = #{cla}
AND t.TEACHER_TYPE = #{teacherType}
AND u.NAME LIKE CONCAT('%', #{name}, '%')
ORDER BY u.USER_NAME

mapper.update:
UPDATE g_user
USER_NAME = #{userName}, NAME = #{name}, PASSWORD = #{password},
WHERE USER_ID = #{userId}
